package app.vpslabs.dashboard;
import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;import org.json.JSONObject;
public class LabsPerfWidget extends AppWidgetProvider{
 @Override public void onEnabled(Context c){WidgetHttp.scheduleAutoRefresh(c);}@Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if("app.vpslabs.dashboard.REFRESH_WIDGET".equals(i.getAction())){int id=i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);if(id!=AppWidgetManager.INVALID_APPWIDGET_ID)update(c,AppWidgetManager.getInstance(c),id);}}@Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){WidgetHttp.scheduleAutoRefresh(c);for(int id:ids)update(c,m,id);}
 static void update(final Context c,final AppWidgetManager m,final int id){RemoteViews v=views(c,"—","—","—","Menghubungkan server…");bind(c,v,id);m.updateAppWidget(id,v);new Thread(new Runnable(){public void run(){updateSync(c,m,id);}}).start();}
 static void updateSync(Context c,AppWidgetManager m,int id){String cpu="—",ram="—",disk="—",meta;try{JSONObject d=WidgetHttp.get(c,"/api/overview");cpu=WidgetHttp.percent(d.optDouble("cpu",0))+"%";ram=WidgetHttp.percent(d.optDouble("memory",0))+"%";disk=WidgetHttp.percent(d.optDouble("disk",0))+"%";meta=d.optInt("processes",0)+" proses · "+WidgetHttp.updatedNow();}catch(Exception e){meta=WidgetHttp.errorText(e);}RemoteViews v=views(c,cpu,ram,disk,meta);bind(c,v,id);m.updateAppWidget(id,v);}
 private static RemoteViews views(Context c,String cpu,String ram,String disk,String meta){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_perf);v.setTextViewText(R.id.wp_title,WidgetHttp.brand(c));v.setTextViewText(R.id.wp_cpu,cpu);v.setTextViewText(R.id.wp_ram,ram);v.setTextViewText(R.id.wp_disk,disk);v.setTextViewText(R.id.wp_meta,meta);return v;}private static void bind(Context c,RemoteViews v,int id){v.setOnClickPendingIntent(R.id.wp_root,WidgetHttp.openPage(c,"performance",21));v.setOnClickPendingIntent(R.id.wp_refresh,WidgetHttp.refresh(c,LabsPerfWidget.class,id,2100));}}
